/* -------------------------------------------------------------------------
   2. PARSING DU CSV
   ------------------------------------------------------------------------- */

function parseFrenchNumber(raw) {
  if (raw === undefined || raw === null) return 0;
  const cleaned = String(raw).trim().replace(/"/g, "");
  if (cleaned === "") return 0;
  const num = parseFloat(cleaned.replace(",", "."));
  return Number.isNaN(num) ? 0 : num;
}

// Convertit "hh:mm:ss" en minutes décimales, pour recalculer le m/min nous-mêmes
// plutôt que de faire confiance à la colonne "Meterage Per Minute" du fichier.
function parseDurationToMinutes(raw) {
  if (!raw) return 0;
  const parts = String(raw).trim().split(":").map((p) => parseInt(p, 10) || 0);
  if (parts.length === 3) {
    const [h, m, s] = parts;
    return h * 60 + m + s / 60;
  }
  if (parts.length === 2) {
    const [m, s] = parts;
    return m + s / 60;
  }
  return 0;
}

function splitCsvLine(line) {
  // Le séparateur est ";" et certains champs sont entourés de guillemets.
  const cells = [];
  let current = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      inQuotes = !inQuotes;
    } else if (ch === ";" && !inQuotes) {
      cells.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  cells.push(current);
  return cells.map((c) => c.trim());
}

/**
 * Transforme le texte brut du CSV en :
 *  - meta: { date, durationSeconds, numPlayers }
 *  - rows: tableau d'objets { player, periodName, distance, vmax, ... }
 */
function parseCsv(text) {
  const cleanText = text.replace(/^\uFEFF/, ""); // retire le BOM en début de fichier
  const lines = cleanText.split(/\r\n|\n|\r/).filter((l) => l.trim() !== "");

  const meta = { date: null, durationSeconds: null };
  let headerIndex = -1;
  let headerCells = [];

  for (let i = 0; i < lines.length; i++) {
    const cells = splitCsvLine(lines[i]);
    const firstCell = cells[0].replace(/"/g, "");

    if (firstCell.toLowerCase().startsWith("date")) {
      meta.date = cells[1];
    }
    if (firstCell.toLowerCase().startsWith("duration")) {
      meta.durationSeconds = parseFrenchNumber(cells[1]);
    }
    if (firstCell === "Player Name") {
      headerIndex = i;
      headerCells = cells.map((c) => c.replace(/"/g, ""));
      break;
    }
  }

  if (headerIndex === -1) {
    throw new Error(
      "Colonne « Player Name » introuvable : ce fichier ne ressemble pas à un export GPS attendu."
    );
  }

  // index de chaque colonne utile
  const colIndex = {};
  Object.entries(COLUMN_MAP).forEach(([key, columnName]) => {
    colIndex[key] = headerCells.indexOf(columnName);
  });

  const missing = Object.entries(colIndex)
    .filter(([, idx]) => idx === -1)
    .map(([key]) => key);
  if (missing.length) {
    throw new Error(
      "Colonnes manquantes dans le CSV : " +
        missing.map((k) => COLUMN_MAP[k]).join(", ") +
        ". Vérifiez COLUMN_MAP dans app.js."
    );
  }

  const rows = [];
  for (let i = headerIndex + 1; i < lines.length; i++) {
    const cells = splitCsvLine(lines[i]).map((c) => c.replace(/"/g, ""));
    if (!cells[colIndex.player]) continue;

    rows.push({
      player: cells[colIndex.player],
      periodName: cells[colIndex.periodName],
      durationMinutes: parseDurationToMinutes(cells[colIndex.duration]),
      distance: parseFrenchNumber(cells[colIndex.distance]),
      vmax: parseFrenchNumber(cells[colIndex.vmax]),
      dist18: parseFrenchNumber(cells[colIndex.dist18]),
      dist24: parseFrenchNumber(cells[colIndex.dist24]),
      marche: parseFrenchNumber(cells[colIndex.marche]),
      accelMax: parseFrenchNumber(cells[colIndex.accelMax]),
      rhie: parseFrenchNumber(cells[colIndex.rhie]),
      accel23: parseFrenchNumber(cells[colIndex.accel23]),
      contacts: parseFrenchNumber(cells[colIndex.contacts]),
    });
  }

  return { meta, rows };
}

/* -------------------------------------------------------------------------
   3. GESTION DE L'EFFECTIF (joueur -> poste)
   ------------------------------------------------------------------------- */

function loadRoster() {
  try {
    const raw = localStorage.getItem(ROSTER_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

function saveRoster(roster) {
  localStorage.setItem(ROSTER_STORAGE_KEY, JSON.stringify(roster));
}

let roster = loadRoster();

function loadRosterPositions() {
  try { return JSON.parse(localStorage.getItem(ROSTER_POSITIONS_KEY) || "{}"); } catch(e) { return {}; }
}
function saveRosterPositions(p) { localStorage.setItem(ROSTER_POSITIONS_KEY, JSON.stringify(p)); }

let rosterPositions = loadRosterPositions();

function loadMatchObjectives() {
  try {
    const raw = localStorage.getItem(MATCH_OBJECTIVES_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch(e) { return {}; }
}
function saveMatchObjectives(o) { localStorage.setItem(MATCH_OBJECTIVES_KEY, JSON.stringify(o)); }
let matchObjectives = loadMatchObjectives();

// État du module match
let matchLastParsed = null;
let matchAliasMap = {}; // { csvName: { officialName, group, position } }

function getPositionsForGroup(group) {
  return ALL_POSITIONS[group] || [];
}

function renderRosterTable() {
  const body = document.getElementById("rosterBody");
  body.innerHTML = "";
  const names = Object.keys(roster).sort((a, b) => a.localeCompare(b));

  names.forEach((name) => {
    const tr = document.createElement("tr");

    const tdName = document.createElement("td");
    tdName.textContent = name;
    tr.appendChild(tdName);

    // Colonne Groupe
    const tdGroup = document.createElement("td");
    const selectGroup = document.createElement("select");
    GROUPS.forEach((g) => {
      const opt = document.createElement("option");
      opt.value = g;
      opt.textContent = g;
      if (roster[name] === g) opt.selected = true;
      selectGroup.appendChild(opt);
    });

    // Colonne Poste (dépend du groupe)
    const tdPosition = document.createElement("td");
    const selectPos = document.createElement("select");

    function rebuildPositionSelect(group) {
      selectPos.innerHTML = "<option value=''>— poste —</option>";
      getPositionsForGroup(group).forEach((p) => {
        const opt = document.createElement("option");
        opt.value = p;
        opt.textContent = p;
        if ((rosterPositions[name] || "") === p) opt.selected = true;
        selectPos.appendChild(opt);
      });
    }
    rebuildPositionSelect(roster[name]);

    selectGroup.addEventListener("change", () => {
      roster[name] = selectGroup.value;
      saveRoster(roster);
      rebuildPositionSelect(selectGroup.value);
      rerenderIfLoaded();
    });
    selectPos.addEventListener("change", () => {
      rosterPositions[name] = selectPos.value;
      saveRosterPositions(rosterPositions);
    });

    tdGroup.appendChild(selectGroup);
    tr.appendChild(tdGroup);
    tdPosition.appendChild(selectPos);
    tr.appendChild(tdPosition);

    const tdRemove = document.createElement("td");
    const removeBtn = document.createElement("button");
    removeBtn.textContent = "Retirer";
    removeBtn.className = "remove-btn";
    removeBtn.addEventListener("click", () => {
      delete roster[name];
      delete rosterPositions[name];
      saveRoster(roster);
      saveRosterPositions(rosterPositions);
      renderRosterTable();
      rerenderIfLoaded();
    });
    tdRemove.appendChild(removeBtn);
    tr.appendChild(tdRemove);

    body.appendChild(tr);
  });
}

function addPlayerToRoster(name, group, position) {
  if (!name.trim()) return;
  roster[name.trim()] = group;
  if (position) rosterPositions[name.trim()] = position;
  saveRoster(roster);
  saveRosterPositions(rosterPositions);
  renderRosterTable();
  rerenderIfLoaded();
}

/* -------------------------------------------------------------------------
   3bis. ASSOCIATION "nom dans le CSV" -> "joueur du listing pro"
   Cette association n'est PAS mémorisée entre les séances : le nom qui sort
   du boîtier GPS ne correspond pas forcément au même joueur d'une séance à
   l'autre (boîtiers non attribués de façon fixe). Elle ne vaut donc que
   pour la séance en cours, et repart à zéro à chaque nouveau CSV importé.
   ------------------------------------------------------------------------- */

let aliasMap = {};

// Retourne le nom officiel (listing pro) correspondant à un nom du CSV,
// ou null si aucune association n'existe encore pour cette séance.
function resolveOfficialName(csvName) {
  if (aliasMap[csvName] && roster[aliasMap[csvName]]) return aliasMap[csvName];
  if (roster[csvName]) return csvName;
  return null;
}

function setAlias(csvName, officialName) {
  aliasMap[csvName] = officialName;
}

