const HALF_PERIOD_NAMES = [
  "mi-temps 1","mi-temps 2","mi temps 1","mi temps 2",
  "half 1","half 2","m1","m2","1st half","2nd half",
  "première mi-temps","deuxième mi-temps",
];

function isHalfPeriod(name) {
  return HALF_PERIOD_NAMES.some(h => name.toLowerCase().trim() === h);
}

function buildMatchPlayerStats(rows) {
  const sessionRows = rows.filter(r => r.periodName === SESSION_PERIOD_VALUE);
  return sessionRows.map(r => {
    const pctHi = r.distance > 0 ? (r.dist18 * 100) / r.distance : 0;
    const pctMarche = r.distance > 0 ? (r.marche * 100) / r.distance : 0;
    const meterPerMin = r.durationMinutes > 0 ? r.distance / r.durationMinutes : 0;
    const hsrPerMin = r.durationMinutes > 0 ? r.dist18 / r.durationMinutes : 0;
    const thiPerMin = r.durationMinutes > 0 ? r.dist24 / r.durationMinutes : 0;
    const accelPerMin = r.durationMinutes > 0 ? r.accel23 / r.durationMinutes : 0;
    const contactPerMin = r.durationMinutes > 0 ? r.contacts / r.durationMinutes : 0;
    return { ...r, pctHi, pctMarche, meterPerMin, hsrPerMin, thiPerMin, accelPerMin, contactPerMin };
  });
}

function buildMatchHalfStats(rows, halfPeriod) {
  const halfRows = rows.filter(r => r.periodName.toLowerCase().trim() === halfPeriod.toLowerCase().trim());
  return halfRows.map(r => {
    const pctHi = r.distance > 0 ? (r.dist18 * 100) / r.distance : 0;
    const pctMarche = r.distance > 0 ? (r.marche * 100) / r.distance : 0;
    const meterPerMin = r.durationMinutes > 0 ? r.distance / r.durationMinutes : 0;
    const hsrPerMin = r.durationMinutes > 0 ? r.dist18 / r.durationMinutes : 0;
    const thiPerMin = r.durationMinutes > 0 ? r.dist24 / r.durationMinutes : 0;
    const accelPerMin = r.durationMinutes > 0 ? r.accel23 / r.durationMinutes : 0;
    const contactPerMin = r.durationMinutes > 0 ? r.contacts / r.durationMinutes : 0;
    return { ...r, pctHi, pctMarche, meterPerMin, hsrPerMin, thiPerMin, accelPerMin, contactPerMin };
  });
}

function groupMatchPlayers(stats) {
  const groups = { "3/4": [], Avant: [], "Non classé": [] };
  stats.forEach(s => {
    const alias = matchAliasMap[s.player];
    const official = alias ? alias.officialName : (roster[s.player] ? s.player : null);
    if (official && roster[official]) {
      const grp = roster[official];
      const pos = (alias && alias.position) || rosterPositions[official] || "";
      if (groups[grp]) groups[grp].push({ ...s, officialName: official, displayName: official, position: pos });
    } else {
      groups["Non classé"].push({ ...s, displayName: s.player, position: "" });
    }
  });
  return groups;
}

function sortByPosition(players, group) {
  const order = ALL_POSITIONS[group] || [];
  return [...players].sort((a, b) => {
    const ia = order.indexOf(a.position || "");
    const ib = order.indexOf(b.position || "");
    if (ia === -1 && ib === -1) return (a.displayName || "").localeCompare(b.displayName || "");
    if (ia === -1) return 1;
    if (ib === -1) return -1;
    return ia - ib;
  });
}

function getMatchObjective(position, key) {
  const raw = matchObjectives[position] && matchObjectives[position][key];
  if (raw === undefined || raw === null || raw === "") return null;
  const num = parseFrenchNumber(raw);
  return Number.isFinite(num) ? num : null;
}

function renderMatchGroupTable(groupName, stats) {
  const visibleColumns = getVisibleMetricColumns();
  const sortedStats = sortByPosition(stats, groupName);

  const wrapper = document.createElement("div");
  wrapper.className = "group-block";
  const titleBar = document.createElement("div");
  titleBar.className = "group-title-bar";
  titleBar.textContent = groupName;
  wrapper.appendChild(titleBar);

  if (!sortedStats.length) {
    const empty = document.createElement("p");
    empty.style.cssText = "padding:10px;margin:0;border:1px solid #ccc;";
    empty.textContent = "Aucun joueur dans ce groupe.";
    wrapper.appendChild(empty);
    return wrapper;
  }

  const podiumRow = document.createElement("div");
  podiumRow.className = "podium-row";
  podiumRow.appendChild(renderPodiumCard("Accel max", findLeader(sortedStats, "accelMax"), "accelMax", "", 2));
  podiumRow.appendChild(renderPodiumCard("Vmax", findLeader(sortedStats, "vmax"), "vmax", " km/h", 2));
  const sp2 = getPodiumSpeedMetric();
  podiumRow.appendChild(renderPodiumCard(sp2.label, findLeader(sortedStats, sp2.key), sp2.key, " m", 0));
  wrapper.appendChild(podiumRow);

  const leaders = {};
  visibleColumns.forEach(col => { leaders[col.key] = findLeader(sortedStats, col.key); });

  const table = document.createElement("table");
  table.className = "data-table";
  const thead = document.createElement("thead");
  thead.innerHTML = "<th>Joueur</th>" + visibleColumns.map(c => `<th>${c.abbr || c.label}</th>`).join("");
  table.appendChild(thead);

  const tbody = document.createElement("tbody");
  sortedStats.forEach(s => {
    const tr = document.createElement("tr");
    const tdName = document.createElement("td");
    tdName.innerHTML = s.position ? `<span class="position-badge">${s.position}</span>${s.displayName || s.player}` : (s.displayName || s.player);
    tr.appendChild(tdName);

    visibleColumns.forEach(col => {
      const isLeader = leaders[col.key] && (leaders[col.key].displayName || leaders[col.key].player) === (s.displayName || s.player);
      const met = OBJECTIVE_KEYS.has(col.key) ? (getMatchObjective(s.position, col.key) !== null ? s[col.key] >= getMatchObjective(s.position, col.key) : null) : null;
      const isRecord = (col.key === "vmax" || col.key === "accelMax") && s.displayName && seasonRecords[s.displayName] &&
        s[col.key] > 0 && (col.key === "vmax" ? s[col.key] >= seasonRecords[s.displayName].vmax && seasonRecords[s.displayName].vmax > 0 : s[col.key] >= seasonRecords[s.displayName].accel && seasonRecords[s.displayName].accel > 0);

      const colMax = leaders[col.key] ? leaders[col.key][col.key] : 0;
      const pct = colMax > 0 ? Math.min(100, Math.max(0, (s[col.key] / colMax) * 100)) : 0;
      const barColor = met === true ? "rgba(127, 209, 127, 0.9)" : "rgba(26, 26, 26, 0.12)";

      const td = document.createElement("td");
      td.style.background = `linear-gradient(to right, ${barColor} ${pct}%, transparent ${pct}%)`;
      if (met === true) td.classList.add("obj-met");
      if (isLeader) td.dataset.leader = "1";
      td.textContent = fmt(s[col.key], col.decimals) + (isRecord ? " ⭐" : "");
      if (isLeader) {
        const ls = document.createElement("span");
        ls.textContent = " ★";
        ls.style.color = "var(--red)";
        ls.style.fontWeight = "bold";
        td.appendChild(ls);
      }
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  wrapper.appendChild(table);

  const firstPosition = sortedStats.find(s => s.position)?.position || "";
  if (firstPosition) {
    const objTable = document.createElement("table");
    objTable.className = "data-table objectives-table";
    const objThead = document.createElement("thead");
    objThead.innerHTML = `<tr><th>Objectif — ${firstPosition}</th>` + OBJECTIVE_COLUMNS.map(c => `<th>${c.label}</th>`).join("") + "</tr>";
    objTable.appendChild(objThead);
    const objTbody = document.createElement("tbody");
    const objRow = document.createElement("tr");
    objRow.className = "objectives-row";
    let cells = "<td>Cible</td>";
    OBJECTIVE_COLUMNS.forEach(col => {
      const target = getMatchObjective(firstPosition, col.key);
      cells += `<td>${target === null ? "—" : fmt(target, col.key === "distance" ? 0 : 2)}</td>`;
    });
    objRow.innerHTML = cells;
    objTbody.appendChild(objRow);
    objTable.appendChild(objTbody);
    wrapper.appendChild(objTable);
  }

  return wrapper;
}

