function handleFile(file) {
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const { meta, rows } = parseCsv(e.target.result);
      manualOverrides = {}; // nouvelle séance = corrections manuelles repartent à zéro
      aliasMap = {}; // nouvelle séance = associations CSV->joueur repartent à zéro aussi
      activePeriods = new Set();
      detectedPeriods = detectPeriods(rows);
      lastParsed = { meta, rows };
      renderPeriodButtons();
      renderReport(rows, meta);
    } catch (err) {
      alert("Erreur de lecture du CSV : " + err.message);
    }
  };
  reader.readAsText(file, "UTF-8");
}

function initUpload() {
  const dropZone = document.getElementById("dropZone");
  const fileInput = document.getElementById("fileInput");
  const browseBtn = document.getElementById("browseBtn");

  browseBtn.addEventListener("click", () => fileInput.click());

  // Toute la zone est cliquable, pas seulement le petit lien
  dropZone.addEventListener("click", (e) => {
    if (e.target.id === "browseBtn") return; // évite un double déclenchement
    fileInput.click();
  });

  fileInput.addEventListener("change", (e) => {
    if (e.target.files[0]) handleFile(e.target.files[0]);
  });

  ["dragenter", "dragover"].forEach((evt) =>
    dropZone.addEventListener(evt, (e) => {
      e.preventDefault();
      dropZone.classList.add("dragover");
    })
  );
  ["dragleave", "drop"].forEach((evt) =>
    dropZone.addEventListener(evt, (e) => {
      e.preventDefault();
      dropZone.classList.remove("dragover");
    })
  );
  dropZone.addEventListener("drop", (e) => {
    const file = e.dataTransfer.files[0];
    if (file) handleFile(file);
  });
}

function initTabs() {
  const buttons = document.querySelectorAll(".tab-btn");
  buttons.forEach((btn) => {
    btn.addEventListener("click", () => {
      buttons.forEach((b) => b.classList.remove("active"));
      document.querySelectorAll(".tab-panel").forEach((p) => p.classList.remove("active"));
      btn.classList.add("active");
      document.getElementById("tab-" + btn.dataset.tab).classList.add("active");
    });
  });
}

