/* =========================================================================
   SAUVEGARDE / RESTAURATION COMPLÈTE
   ========================================================================= */

const BACKUP_KEYS = [
  ROSTER_STORAGE_KEY,
  ROSTER_POSITIONS_KEY,
  OBJECTIVES_STORAGE_KEY,
  MATCH_OBJECTIVES_KEY,
  SEASON_RECORDS_STORAGE_KEY,
  SAVED_SESSIONS_STORAGE_KEY,
  COLUMN_VISIBILITY_STORAGE_KEY,
  "gpsClubName_v1",
  "gpsSessionTheme_v1",
  "gpsScatterAxes_v1",
];

function exportAllData() {
  const backup = { version: 2, exportedAt: new Date().toISOString(), data: {} };
  BACKUP_KEYS.forEach(key => {
    const val = localStorage.getItem(key);
    if (val) backup.data[key] = JSON.parse(val);
  });
  const blob = new Blob([JSON.stringify(backup, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  const date = new Date().toLocaleDateString("fr-FR").replace(/\//g,"-");
  a.download = `nissa-rugby-backup-${date}.json`;
  a.click();
  URL.revokeObjectURL(url);
  const status = document.getElementById("backupStatus");
  if (status) status.textContent = `✓ Sauvegarde exportée le ${new Date().toLocaleString("fr-FR")}`;
}

function importAllData(file) {
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const backup = JSON.parse(e.target.result);
      const data = backup.data || backup; // compat ancien format
      let count = 0;
      Object.entries(data).forEach(([key, val]) => {
        if (BACKUP_KEYS.includes(key)) {
          localStorage.setItem(key, JSON.stringify(val));
          count++;
        }
      });
      // Recharger toutes les données en mémoire
      roster = loadRoster();
      rosterPositions = loadRosterPositions();
      objectives = loadObjectives();
      matchObjectives = loadMatchObjectives();
      seasonRecords = loadSeasonRecords();
      savedSessions = loadSavedSessions();
      columnVisibility = loadColumnVisibility();
      // Re-rendre tous les panneaux
      renderRosterTable();
      renderObjectivesPanel();
      renderColumnToggles();
      renderMatchObjectivesPanel();
      renderStatsTab();
      renderRecordsTab();
      rerenderIfLoaded();
      const status = document.getElementById("backupStatus");
      if (status) status.textContent = `✓ ${count} éléments restaurés avec succès — rechargez la page si nécessaire.`;
      alert(`✓ Restauration réussie ! ${count} éléments chargés.`);
    } catch (err) {
      alert("Fichier invalide ou corrompu : " + err.message);
    }
  };
  reader.readAsText(file);
}

function initBackup() {
  document.getElementById("backupAllBtn").addEventListener("click", exportAllData);
  const restoreInput = document.getElementById("restoreAllInput");
  document.getElementById("restoreAllBtn").addEventListener("click", () => restoreInput.click());
  restoreInput.addEventListener("change", e => {
    if (e.target.files[0]) importAllData(e.target.files[0]);
  });
}

document.addEventListener("DOMContentLoaded", () => {
  initUpload();
  initTabs();
  initRosterUI();
  initExport();
  renderObjectivesPanel();
  renderColumnToggles();
  renderStatsTab();
  initRecordsUI();
  initHeaderFields();
  initMatchTab();
  renderMatchObjectivesPanel();
  initBackup();
});

